# Generated by Cursor (TDD plan item 7: complex $<X> [= N])
"""Scan for editorial dollar/pound: $<...> [= N] or £<...> [= N]; emit (rule_id, start, span, path_str)."""

import re

# $<...> [= N] or £<...> [= N]; N may contain commas
EDITORIAL_DOLLAR_RE = re.compile(r"\$<[^>]*>\s*\[=\s*[\d,]+\]")
EDITORIAL_POUND_RE = re.compile(r"£<[^>]*>\s*\[=\s*[\d,]+\]")


def scan_turn_editorial_dollar(
    text: str,
    path_str: str = "",
) -> list[tuple[str, int, str, str]]:
    """Emit (editorial_dollar, start_index, span, path_str) for $<X> [= N] and £<X> [= N]."""
    result: list[tuple[str, int, str, str]] = []
    for m in EDITORIAL_DOLLAR_RE.finditer(text):
        result.append(("editorial_dollar", m.start(), m.group(0), path_str))
    for m in EDITORIAL_POUND_RE.finditer(text):
        result.append(("editorial_dollar", m.start(), m.group(0), path_str))
    return result
